rowdata.pyStepsJavaSource:
ProcessingStatus psStatus = tools.getStepStatus();  
String strSubject = tools.getParamValue("Subject");
String strTo=tools.getParamValue("To");

// handling the page.property in the smart shape's TO mail id
String[] toIds=strTo.split(",");
String tempToStrng="";
strErrorMessage="";
for(String to:toIds){
try{
if(!to.isEmpty())
{
    if(!(to.contains("@"))&&!(to.startsWith(".")))
          {
      			// handling the page.property in the smart shape's TO mail id
           String toMailID = tools.getIfPresent(to).getStringValue();
           tempToStrng+=toMailID+",";
           }else{
      tempToStrng=tempToStrng+to+",";
    }
}else{
   tempToStrng=tempToStrng+to+",";
    //dontSendMail = true;
}
}
  catch(Exception e){
    tempToStrng=tempToStrng+to+",";
}
}
tempToStrng=tempToStrng.replaceAll(",$","");

 tools.putParamValue("To",tempToStrng);

// If there are any property references in the subject
int nIndexSubject = strSubject.indexOf("{");
if (nIndexSubject >= 0)
{
	strSubject =  "= \"" + strSubject;
	strSubject = com.pegarules.generated.pega_rules_string.replaceAll(strSubject,"{","\"+");
	strSubject = com.pegarules.generated.pega_rules_string.replaceAll(strSubject,"}","+ \"");
	strSubject += " \"";

	// Evaluate property references
	String[] arSubject = new String[2];	
	boolean bSubjectResult = com.pegarules.generated.pega_rules_decision.EvaluateExpression(tools,myStepPage,strSubject,arSubject);

	// Set evaluated string as the subject
	if (bSubjectResult)
	{
		tools.putParamValue("Subject",arSubject[0]);
	}		
}

String strMessage = tools.getParamValue("Message");
//in case of message
if(tools.getParamValue("CorrName") == "") {
  //US-198027 - Skip Property Evaluation to honour Custom CSS braces { } when message body is sent.
  // PreRequsite is to resolve all the property references before calling the Send Simple Email API if there are present in the Message Body 
boolean bSkipPropertyEvaluation = tools.getParamAsBoolean(ImmutablePropertyInfo.TYPE_TRUEFALSE, "skipPropertyEvaluation");
// If there are any property references in the message
int nIndexMessage = strMessage.indexOf("{");
if (!bSkipPropertyEvaluation && nIndexMessage >= 0)
{
	strMessage =  "= \"<html>" + strMessage;
    strMessage = com.pegarules.generated.pega_rules_string.replaceAll(strMessage,"{","\"+");
	strMessage = com.pegarules.generated.pega_rules_string.replaceAll(strMessage,"}","+ \"");
	strMessage += "</html>\"";

	// Evaluate property references
	String[] arMessage = new String[2];	
	boolean bMessageResult = com.pegarules.generated.pega_rules_decision.EvaluateExpression(tools,myStepPage,strMessage,arMessage);

	// Set evaluated string as the subject
	if (bMessageResult)
	{
		tools.putParamValue("Message",arMessage[0]);
	}
}
}
// If the java failed we still don't want a bad status, so reset it
//tools.getStepStatus().set(psStatus);
tools.getStepStatus().backoutWorst();

// java step, since these properties only exist on Data-Corr-Email object
ClipboardProperty pyFromParty = myStepPage.getIfPresent("pyFromParty");
ClipboardPage workpage=tools.getPrimaryPage();
if(pyFromParty != null && !pyFromParty.isEmpty() ){
  String propEmail=".pyWorkParty("+pyFromParty+").pyEmail1";
  if(workpage.getIfPresent(propEmail) != null){
    myStepPage.putString(".pyFrom", workpage.getProperty(propEmail).getStringValue());
  }else{
    myStepPage.putString(".pyFrom", tools.getParamValue("EmailAddress"));
  }
}
else{
 myStepPage.putString(".pyFrom", tools.getParamValue("EmailAddress"));
}
